/**
 * Every byte a new skill starts life with.
 *
 * Pure functions: spec + house facts in, {path, content} out. No clock, no
 * network, no randomness — which is what lets the emitted tree be pinned
 * byte-exactly as a baseline, for the same reason shipflow pins its rendered
 * workflow and press pins its emitted regions. When the generated bytes ARE the
 * contract, one changed character is a change to every skill made after it.
 *
 * Two deliberate omissions from this file: the press masthead on the caller
 * workflow, and the press:agent-ui region in SKILL.md. Both are *stamped* after
 * the tree lands, by press and forge themselves. A brand value written down
 * here would be the ninth hand-ported copy of the thing press exists to end.
 */

const ORG = 'natejswenson';
const REPO = 'claude-skills';
const AUTHOR = 'Nate Swenson';
const NPM_SCOPE = '@natjswenson';

const j = (obj) => `${JSON.stringify(obj, null, 2)}\n`;

/* ------------------------------------------------------------------ plugin root */

